package com.collabspace.config; import com.collabspace.websocket.WebSocketAuthInterceptor; import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.Configuration; import org.springframework.messaging.simp.config.*; import org.springframework.web.socket.config.annotation.*; @Configuration @EnableWebSocketMessageBroker @RequiredArgsConstructor public class WebSocketConfig implements WebSocketMessageBrokerConfigurer {private final WebSocketAuthInterceptor interceptor; public void configureMessageBroker(MessageBrokerRegistry r){r.enableSimpleBroker("/topic","/queue");r.setApplicationDestinationPrefixes("/app");r.setUserDestinationPrefix("/user");} public void registerStompEndpoints(StompEndpointRegistry r){r.addEndpoint("/ws").setAllowedOriginPatterns("*").withSockJS();r.addEndpoint("/ws").setAllowedOriginPatterns("*");} public void configureClientInboundChannel(ChannelRegistration r){r.interceptors(interceptor);}}